SELECT EXTRACT(MINUTE FROM "EventTime") AS M, COUNT(*) AS PageViews FROM hits WHERE "CounterID" = 62 AND "EventDate" >= '2013-07-14' AND "EventDate" <= '2013-07-15' AND "IsRefresh" = 0 AND "DontCountHits" = 0 GROUP BY EXTRACT(MINUTE FROM "EventTime") ORDER BY EXTRACT(MINUTE FROM "EventTime") LIMIT 10 OFFSET 1000;